CREATE proc [dbo].[GetPhysicalBranchBalance] @BRId as int, @DId as int  as Select i.ItemId,i.Item,u.Unit,u.UId,  cast((Select left( (Select isnull(Sum(Qty),0) from WareHouse_Branch where [Type]='In' and ItemId=i.ItemId and BRId=@BRId and DId = @DId)  - (Select isnull(Sum(Qty),0) from WareHouse_Branch where [Type]='Out' and ItemId=i.ItemId  and BRId=@BRId and DId = @DId), len((Select isnull(Sum(Qty),0) from WareHouse_Branch where [Type]='In' and ItemId=i.ItemId and BRId=@BRId and DId = @DId)  - (Select isnull(Sum(Qty),0) from WareHouse_Branch where [Type]='Out' and ItemId=i.ItemId  and BRId=@BRId and DId = @DId))-2 )) as decimal(18,2))as Balance,   isnull([dbo].uspGetItemAvgRateKitchenDeptFunc(@BRId,@DId,i.ItemId,null,0),0) as RatePerPcs  From Item i  inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit u on iu.IssUnit=u.Uid order by i.Item  